Passing An Array
int ListMinimum(const int A[], int asize) {
 assert(asize >= 1);
 int SmallestValueSoFar = A[0];
 for (int i = 1; i < asize; ++i) {
 if (A[i] < SmallestValueSoFar ) {
 SmallestValueSoFar = A[i];
 }
 return SmallestValueSoFar ;

